# -*- coding: utf-8 -*-
"""逐问解读（中）：问91–152，神向人所要求的本分——律法与十诫。"""

from unit import U

UNITS = [

U("u21", "问91–97", "本分的规则：道德律，与它在堕落之后的三种用处",
  [(91, "神向人所要求的本分是什么？", "顺服祂<b>所启示的</b>旨意。"),
   (92, "神起初向人启示的顺服准则是什么？", "在无罪状态中向亚当、并在他里面向全人类所启示的顺服准则，除了「不可吃分别善恶树果子」这条特别的命令之外，就是<b>道德律</b>。"),
   (93, "道德律是什么？", "道德律是神向人类宣告祂的旨意，指导并约束各人，在全人（灵魂与身体）的构造与性情上、并在他对神与人所欠的一切圣洁公义的本分上，作出<b>亲身的、完全的、持续的</b>顺服；守全则应许生命，违犯则威胁死亡。"),
   (94, "堕落之后道德律还有用吗？", "堕落以后无人能靠道德律得着义与生命；然而它仍有极大的用处——有对众人共通的，也有分别对未重生者与重生者特有的。"),
   (95, "道德律对众人共通的用处是什么？", "它告诉人神圣洁的本性与旨意，以及人的本分，约束人照此而行；<b>使人确信自己无力遵行，并看见自己本性、内心与生活的罪污</b>；使人因此自卑，更清楚看见自己需要基督，也看见祂顺服的完全。"),
   (96, "道德律对未重生者有何特别用处？", "唤醒他们的良心，逃避将来的忿怒，驱使他们归向基督；或者，若他们仍留在罪中，就使他们<b>无可推诿</b>，并处在律法的咒诅之下。"),
   (97, "道德律对重生者有何特别用处？", "重生并信基督的人，虽已<b>从作为行为之约的道德律中得了释放</b>——不再靠它称义，也不再受它定罪；但除了与众人共通的用处之外，它对他们还有特别的用处：叫他们看见基督为他们成全律法、并代受咒诅是何等大的恩，因而激发他们更多的感恩，并把这感恩表现在<em>更加谨慎地照着它——作为他们顺服的准则——而行</em>。")],
  core="问 97 是整个第二大部的门轴。它用一句话同时说了两件必须同时成立的事：<b>律法作为「行为之约」已经终结</b>（不再是我称义的途径，也不再能定我的罪），<b>律法作为「顺服的准则」仍然有效</b>。前半句救我脱离律法主义，后半句救我脱离反律主义。",
  why="1640 年代伦敦的反律主义争议是真实而激烈的（Tobias Crisp 等人的讲道引发全城辩论）。反律派说：既然基督已经成全了律法，信徒与律法再无关系。问 97 的回答不是折中，而是精确划界——<em>关系变了，不是关系没了</em>：从法庭上的起诉书，变成父家里的家规。",
  cont="海德堡把十诫整个放在<b>第三部分「感恩」</b>之下（问 86 以下），位置比威敏更直白地表达了同一个神学。海德堡问 115 更是问 97 的孪生问：「<em>既然今生无人能守全十诫，神为何还要如此严格地传讲？</em>」答有两层——「叫我们一生越发认识自己的罪性，因而更加切慕在基督里的赦罪与义；也叫我们不断恳求圣灵的恩典，越来越照神的形像被更新，直到今生之后达到完全的目标。」<b>威敏说「感恩的准则」，海德堡说「认罪＋更新」，两者合起来才是律法第三用的全貌。</b>",
  view="律法三用（<span class=\"lt\">usus triplex legis</span>）是路德宗与改革宗共有的框架，但重心不同：路德宗强调第一用（镜子），对第三用较为谨慎；<b>改革宗以第三用为「律法的主要用处」（加尔文语）</b>。这不是谁更律法主义，而是对「福音之后的生活」持不同的期待。大要理后面 50 多问的篇幅，就是这个立场的具体展开。",
  app="判断自己是否真明白问 97，有一个简单的测试：读到十诫的严格要求时，你的第一反应是恐惧（说明你仍把它当行为之约），还是感恩加上渴慕（说明你已在恩典之约里读它）？",
  keys="弥6:8　罗2:14–15　加3:10,12　罗3:20　罗7:7　提前1:8　加3:13　罗6:14　罗7:22　多2:11–14"),

U("u22", "问98–102", "十诫总论：结构、八条解经规则、序言",
  [(98, "道德律的总纲在哪里？", "在十诫中（出20章、申5章）。<b>前四诫是我们对神的本分，后六诫是我们对人的本分。</b>"),
   (99, "正确理解十诫应遵守哪些规则？", "八条（详见第三部第三节）。其中最关键的三条是：律法是<b>属灵</b>的，管到心思意念；<b>命令即禁止其反面，禁止即命令其反面</b>；禁止一罪，即连同其一切同类、肇因、途径与表象一并禁止。"),
   (100, "在十诫中我们要特别注意什么？", "三样：序言、诫命的本身，以及附加在某些诫命上的<em>加强理由</em>。"),
   (101, "十诫的序言是什么？", "「我是耶和华你的神，曾将你从埃及地为奴之家领出来。」——神在此显明祂的<b>主权</b>（祂是耶和华，永恒、不变、全能，其存有在自己里面、也出于自己，并赐存有于祂一切的话与作为）；显明祂是<b>立约的神</b>，如同当日对以色列，今日也对祂一切的子民；祂既领他们出埃及为奴之地，也照样救我们脱离属灵的辖制。<em>因此我们当以祂为我们独一的神，并遵守祂一切的诫命。</em>"),
   (102, "前四诫的总纲是什么？", "尽心、尽性、尽力、尽意，爱主你的神。")],
  core="问 101 是全部十诫的解释学钥匙：<b>诫命的前面先有救赎</b>。神不是先说「你要守法」，而是先说「我已救你出来」。次序即福音——<em>顺服是被救之人的回应，不是求救之人的条件</em>。任何抽掉序言的十诫讲授，都会自动变成律法主义。",
  why="问 100 特别点出「加强的理由」（reasons annexed），是要防止把十诫读成十条孤立的禁令。第二、三、四、五诫各附有理由（问 110、114、120、133），这些理由揭示了诫命背后的<em>神的性情</em>——祂忌邪、祂不以有罪为无罪、祂自己也安息、祂应许长寿。",
  cont="海德堡问 92 列出十诫全文，问 93 分为两版（两块法版），问 94 起逐诫展开。<b>值得注意的是：海德堡与威敏对第二诫的划分一致</b>（都以「不可为自己雕刻偶像」为独立的第二诫，以「不可贪恋」为完整的第十诫），这是改革宗与路德宗／罗马教的一个可见分别——后两者把第一二诫合并，把第十诫拆成两条。数法之争背后是<b>对图像敬拜的态度之争</b>。",
  view="问 98 的「前四／后六」划分，来自耶稣自己对律法的总结（太22:37–40）。这个划分本身就是一种神学宣告：<em>对人的爱不能脱离对神的爱而独立成立，也不能取代它</em>。把十诫读成纯粹的社会伦理，等于把前四诫删掉。",
  app="教导十诫时，请务必先教序言。对儿童尤其如此：先让他知道「神已经救了我们」，再教「所以我们这样活」。次序颠倒，教出来的是惧怕，不是爱。",
  keys="出20:1–17　申5:6–21　太22:37–40　路1:74–75　彼前1:15–18"),

U("u23", "问103–106", "第一诫：以谁为神",
  [(103, "第一诫是什么？", "「除了我以外，你不可有别的神。」"),
   (104, "第一诫所要求的本分是什么？", "认识并承认神是唯一的真神，也是<em>我们的</em>神，并照此敬拜荣耀祂：思念、默想、记念、高举、尊崇、敬爱、拣选、爱慕、渴慕、敬畏祂；信祂、倚靠祂、指望祂、以祂为乐、因祂欢喜；为祂发热心；求告祂，将一切的赞美感谢归给祂；以全人顺服顺从祂；凡事谨慎讨祂喜悦，在任何事上得罪了祂就忧伤；并与祂谦卑同行。"),
   (105, "第一诫所禁止的罪是什么？", "无神论；偶像崇拜；不以神为神；对神的无知、遗忘、误解、错误意见、不配与邪恶的想法；大胆好奇地窥探祂的隐秘；亵渎、恨恶神；自爱、自求、把心思意念过度地放在别的事物上；虚浮的轻信、不信、异端、错信、疑惑、绝望、屡教不改、在神的审判下毫无知觉、心硬、骄傲、擅自妄为、肉体的安逸、试探神；使用不法的手段、倚靠合法的手段；肉体的享乐；败坏、盲目、失当的热心；不冷不热、在属神的事上死气沉沉；自己与神疏远、背道；向圣徒、天使或任何受造物祷告或献上宗教性的敬拜；与魔鬼立约、求问交鬼的；<b>使人作我们信仰与良心的主</b>；轻慢藐视神与祂的命令；抗拒并叫圣灵担忧；对祂的安排不满与不耐烦；愚昧地为祂所降的灾祸责怪祂；把我们所是、所有、所能行的任何良善的称赞，归给运气、偶像、自己或任何别的受造物。"),
   (106, "「在我面前」这句话特别教导我们什么？", "神看见万事，祂<b>特别注意、极其不悦</b>「以别的为神」这罪。这既是劝阻，也加重了此罪——<em>在祂眼前另立别神，是最放肆的挑衅</em>。")],
  core="问 104–105 的两张清单示范了问 99 第四条规则（命令即禁止其反面）的全面应用。<b>第一诫不是「不要拜偶像」这么窄</b>：它管到我的思念、渴慕、倚靠、喜乐所在。凡我最惧怕、最渴望、最倚靠的，就是我实际上的神。",
  why="问 105 中「<b>使人作我们信仰与良心的主</b>」一句，是对罗马教教权的直接指控，也是对任何形式的属灵专权的禁令。请注意它被列在第一诫之下——<em>让人代替神成为良心的最高权威，本质上是拜偶像</em>。这一句在今日同样适用于任何以领袖取代圣经权威的团体。",
  cont="海德堡问 94–95 处理第一诫，问 95 给出偶像的著名定义：「<b>偶像就是人在神——那位在祂的道中启示自己的独一真神——之外或之旁，所捏造或据有、用以寄托信靠的任何东西。</b>」这个定义比威敏的长清单更利于记诵，且更能穿透现代处境（工作、家庭、成就都可以成为偶像）。<em>清单适合省察，定义适合诊断，两者各有其用。</em>",
  view="问 105 里「<b>倚靠合法的手段</b>」是一句极精妙的话：使用合法手段是本分，<em>倚靠</em>合法手段却是罪。药、医生、储蓄、计划都是神所赐的手段；把终极的信靠放在它们身上，就越过了界线。这一条最难省察，也最常被违犯。",
  app="第一诫的自我省察，可以用四个问题：我最怕失去什么？我最想得到什么？我出事时第一个求告谁？我成功时把功劳归给谁？四个答案指向同一个东西时，那就是我实际的神。",
  keys="书24:15　申26:17　太4:10　诗29:2　罗1:21　耶2:27–28　林后1:9　诗14:1　结14:5"),

U("u24", "问107–110", "第二诫：如何敬拜，与那条被删去的短语",
  [(107, "第二诫是什么？", "「不可为自己雕刻偶像，也不可作什么形像仿佛上天、下地和地底下、水中的百物……」"),
   (108, "第二诫所要求的本分是什么？", "领受、遵守、并<b>纯正完整地保守</b>一切神在祂道中所设立的宗教敬拜与典章；特别是奉基督的名祷告与感恩；读经、讲道、听道；施行与领受圣礼；教会的治理与惩戒；圣职与对圣职的供养；宗教性的禁食；指着神的名起誓与向祂许愿；<em>并且不赞同、憎恶、反对一切假敬拜，按各人的地位与呼召，除去假敬拜与一切偶像的遗迹。</em>"),
   (109, "第二诫所禁止的罪是什么？", "一切设计、建议、命令、使用或以任何方式赞同<b>非神自己所设立的</b>宗教敬拜；〔容忍假宗教；〕为神、或为三位中的任何一位造任何形像，无论是在心里默想的、还是在外面以任何受造物的样式雕塑的；敬拜这形像，或在其中、藉其敬拜神；为虚构的神造形像并敬拜服事之；一切迷信的发明、败坏神的敬拜、对它有所增添或删减——无论是自己发明的，还是从他人传统领受的，无论托名于古老、习俗、虔诚、善意或任何别的藉口；买卖圣职；亵渎圣物；一切忽略、藐视、阻挠、反对神所设立之敬拜与典章的行为。"),
   (110, "第二诫所附的理由是什么？", "「因为我耶和华你的神是<b>忌邪的神</b>……」——显明神对我们的主权、祂对我们的所有权，以及祂对自己敬拜的<em>热忱</em>。祂视一切假敬拜为属灵的淫乱，并要追讨。")],
  core="第二诫管的不是「拜谁」（那是第一诫），而是「<b>怎样拜</b>」。它确立了改革宗所谓的<b>敬拜的规范性原则</b>（<span class=\"lt\">regulativum principium</span>）：<em>唯有神在祂话语中所吩咐的，才可用于公共敬拜</em>。问 109 的「非神自己所设立的」六个字，就是这条原则的全部根据。",
  why="这是十六至十七世纪英国教会最激烈的战场——礼仪书、跪领圣餐、十字圣号、祭衣、风琴、节期。清教徒的立场不是「品味朴素」，而是神学性的：<b>神有权规定祂如何被敬拜；人自创的敬拜，无论出于多好的动机，都是对祂的冒犯。</b>问 109 末句「无论托名于古老、习俗、虔诚、善意」，就是逐条堵死所有为自创敬拜辩护的理由。",
  cont="<b>欧陆在这一点上与威敏完全一致，且表达得更早。</b>比利时信条第 32 条明说：人「不可加添或删减」神所吩咐的，凡人为的规条若要约束良心、强制敬拜，就当弃绝。海德堡问 96–98 论第二诫，问 98 回答「难道图像不可以作为平信徒的书吗？」——答：「不可；因为我们不当自以为比神更聪明，<b>祂不愿祂的百姓藉着哑巴偶像受教，乃愿藉着祂圣道活泼的传讲受教。</b>」这一句是整个改革宗敬拜观最精炼的表述。",
  view="<b>1788 年的删改。</b>「容忍假宗教」（tolerating a false religion）一语在 1788 年被美国长老会从问 109 中删去，OPC、PCA 等沿用删改版；苏格兰自由教会等保留原文。<br>要分清两件事：<em>被删掉的是「政府应否以强制力压制假宗教」这一政治推论</em>；<em>没有被删的是问 108「不赞同、憎恶、反对一切假敬拜」这一教会本分</em>。修订改的是政府论，不是敬拜论。",
  app="规范性原则的现代应用常引发争论，但有一个不争的核心：<b>公共敬拜的中心必须是神所设立的要素</b>——读经、讲道、祷告、唱诗、圣礼、奉献。凡在这些之外被推到中心的东西，无论多有效果，都该被重新审视。",
  keys="出20:4–6　申12:32　太15:9　徒17:24–25　申4:15–19　罗1:21–23　林前11:23"),

U("u25", "问111–114", "第三诫：如何使用祂的名",
  [(111, "第三诫是什么？", "「你不可妄称耶和华你神的名。」"),
   (112, "第三诫所要求的本分是什么？", "凡神藉以使自己被人认识的一切——祂的名、称号、属性、典章、圣道、圣礼、祷告、起誓、许愿、掣签、祂的作为——都当在<b>思想、默想、言语、书写</b>中被圣洁敬虔地使用；并藉着圣洁的宣认与<em>相称的生活</em>，归荣耀于神，使自己与他人得益。"),
   (113, "第三诫所禁止的罪是什么？", "不照上述要求使用神的名；在无知、虚妄、不敬、亵渎、迷信或邪恶地提及使用祂的称号、属性、典章与作为；亵渎；伪证；一切有罪的咒诅、起誓、许愿与掣签；违背自己的誓与愿；<b>对神的谕旨与护理发怨言、争辩、好奇窥探、误用</b>；曲解、误用或以任何方式歪曲神的话；亵慢的嘲笑；以虚伪或不正当的目的作宗教宣认；<em>以信仰为耻，或因不相称、不明智、不结果子、绊倒人的行事为人而使信仰蒙羞</em>。"),
   (114, "第三诫所附的理由是什么？", "「……耶和华必不以他为无罪。」——虽然违犯者常能逃过人的责罚，神却必不放过。祂断不容许他们逃脱祂公义的审判。")],
  core="第三诫的范围远比「不可说脏话」宽。问 112 的关键是最后那句：「<b>藉着圣洁的宣认与相称的生活</b>」。<em>挂着祂的名而活得与祂的名不称，这本身就是妄称祂的名。</em>问 113 末句把这一点说死了：以信仰为耻，或使信仰蒙羞，同样违犯第三诫。",
  why="问 113 中「对神的谕旨与护理发怨言、好奇窥探」被列在这里，很值得留意：<b>这是把「预定论的滥用」当作违犯第三诫来处理</b>。妄图窥探神的隐秘旨意（谁被拣选、为何发生这灾），或据此埋怨祂，都是对祂名的不敬。这是威敏对自己的预定论所作的自我约束。",
  cont="海德堡问 99–102 论第三诫。<b>问 101–102 处理了一个威敏未单列的问题：基督徒可否起誓？</b>答：可以——当政府要求、或为维护真理与邻舍的益处而需要时，因为这是神所许可、旧新约圣徒所行的；但只可指着神的名起誓，不可指着受造物。<em>这是欧陆对再洗礼派「一概不可起誓」立场的正面回应</em>，威敏把这部分放在了信条第 22 章而非要理中，故读大要理的人应当补上这一段。",
  view="问 114 的「必不以他为无罪」是一句可怕而必要的话。第三诫是十诫中<b>最容易在人前逃脱、也最难在神前逃脱</b>的一诫——因为它的违犯多半发生在言语和心思里，没有可见的受害人。附加的理由正是针对这一点。",
  app="一个可行的省察：今天我提到神的名时，有多少次是随口的、习惯性的、或用来为自己的立场加重语气的？「神告诉我」「神的旨意就是」这类表述，若无确据而说，正落在问 113 的清单上。",
  keys="太6:9　申28:58　诗68:4　玛1:11,14　诗50:16–17　雅5:12　彼前3:15　多1:16"),

U("u26", "问115–121", "第四诫：安息日——威敏与欧陆真正的分歧点",
  [(115, "第四诫是什么？", "「当记念安息日，守为圣日……」"),
   (116, "第四诫所要求的本分是什么？", "向神分别为圣、守为圣洁，就是祂在话语中所定的时候，明确地说是<b>七日中的一整日</b>；从世界之初到基督复活，是七日中的第七日；从那以后是七日的<em>第一日</em>，并要如此持续到世界的末了。这就是<b>基督徒的安息日</b>，在新约中称为<em>主日</em>。"),
   (117, "安息日当如何守为圣？", "整日<b>圣洁地安息</b>：不但停止那些任何时候都有罪的事，也停止那些在别的日子本为合法的<em>世俗工作与娱乐</em>；并以整日之时（除了必需与怜悯的工作之外）用在公共与私下的敬拜操练上为乐。为此我们当预备己心，并以预见、殷勤与节制安排、及时了结世上的事务，好使自己在那日更自由、更适合尽那日的本分。"),
   (118, "为何守安息日的责任特别指向家主与在上者？", "因为他们不但自己当守，也<b>有责任使在他们照管之下的人都遵守</b>；而他们常因自己的事务拦阻这些人守日。"),
   (119, "第四诫所禁止的罪是什么？", "一切对上述本分的疏忽；漫不经心、马虎、无益地履行这些本分，或以之为厌烦；以懒惰、或以本身有罪之事玷污这日；并以一切<em>不必要的</em>关乎世俗工作与娱乐的工作、言语、思想玷污这日。"),
   (120, "第四诫所附的理由是什么？", "三重：其一，<b>神慷慨地把六日给了我们自己用</b>，只为自己留下一日（「六日要劳碌」）；其二，祂对这日主张特别的所有权（「第七日是向耶和华你神当守的安息日」）；其三，<b>祂自己的榜样</b>——祂六日造物，第七日安息，「所以耶和华赐福与安息日，定为圣日」。"),
   (121, "为何第四诫开头要放一个「当记念」？", "部分因为记念它有极大的益处，能帮助我们预备守它，也帮助我们更好地遵守其余的诫命；部分因为<b>我们极容易忘记它</b>——这一条的本性之光较少，而它又约束我们在别的时候本为合法之事上的天然自由；它每七日才来一次，其间有许多世俗事务插入、占据我们的心思；<em>并且撒但与他的爪牙极力要抹掉这日的荣耀，甚至抹掉对它的记忆</em>，好引进不敬虔与不虔诚。")],
  core="七问、篇幅极长，这在十诫各诫中是独一份的（第四诫 7 问，第二诫 4 问，第六诫 3 问）。<b>篇幅本身就是立场</b>：威敏视安息日为创造秩序中的永久道德义务，不是仪文律的一部分。问 120 的第三个理由（神自己的榜样）是这个立场的根基——神在<em>创世</em>时就安息了，早于摩西一千多年。",
  why="斗争对象有二：一是当时英格兰王室颁布的《体育诏令》（Book of Sports, 1618／1633 重颁），公开允许主日下午的运动娱乐，清教徒视之为对主日的公然玷污；二是反律主义与一部分大陆传统，认为第四诫属仪文律、已经废止。问 117「连合法的娱乐也当停止」的严格措辞，正是对《体育诏令》的针锋相对。",
  cont="<b>这是威敏与海德堡之间为数不多的实质差异之一，必须诚实面对。</b><br>海德堡问 103 论第四诫：「<em>首先，福音的职事与学校当得维持；我尤其当在安息日殷勤参加神的教会，学习神的道，使用圣礼，在会众中公开求告主，并把我的财物分给穷人。其次，我当一生停止我邪恶的作为，让主藉祂的灵在我里面作工，从而在今生就开始那永远的安息日。</em>」<br>对比之下：<ul><li><b>海德堡</b>的重心在<em>正面的敬拜参与</em>与<em>末世的安息</em>（「在今生就开始永远的安息日」），几乎不谈禁止性的条款。</li><li><b>威敏</b>的重心在<em>整日的分别为圣</em>，明确禁止合法的世俗工作与娱乐。</li></ul>神学上并非对立：两者都承认主日、都以公共敬拜为核心、都不把它当仪文律废除。<em>差别在严格程度与论证路径</em>——威敏从创造之例推出整日的义务，海德堡从新约的实践推出敬拜的优先。历史上欧陆改革宗（尤其荷兰）对娱乐的宽严不一，这一分歧至今存在于改革宗内部，属<b>传统内的合法分歧</b>。",
  view="问 117 的「<b>必需与怜悯的工作</b>」（works of necessity and mercy）是一个至关重要的缓冲条款，来自耶稣自己（太12:1–13）。医生、护士、消防员、照顾病人与幼儿的人，其主日的工作不在禁止之列。忽略这一条款，就会把大要理读成不近人情的严苛——那不是它的本意。",
  app="无论你在严宽之争上站哪一边，问 121 提供了一个双方都能接受的诊断：<em>你是否需要「记念」它？</em>如果主日与其他日子在你的心思与安排上毫无差别，那么无论你的神学立场如何，第四诫在你身上已经失效了。",
  keys="出20:8–11　创2:2–3　赛58:13–14　可2:27–28　启1:10　徒20:7　太12:1–13　尼13:15–22"),

U("u27", "问122–126", "第五诫（上）：权柄的本质与「父母」的范围",
  [(122, "后六诫的总纲是什么？", "爱邻舍如同自己，并且愿意人怎样待你，你也要怎样待人。"),
   (123, "第五诫是什么？", "「当孝敬父母，使你的日子在耶和华你神所赐你的地上得以长久。」"),
   (124, "第五诫中的「父母」指谁？", "不只是<em>肉身的父母</em>，也包括<b>一切在年龄与恩赐上为长者，尤其是按神的设立在我们之上、居于权柄之位的人</b>——无论是在家庭、教会，还是在国家中。"),
   (125, "为什么在上者被称为「父母」？", "为要教导他们在对待下属的一切本分上，<b>像亲生父母一样</b>，照各自的关系流露爱与温柔；也为使下属更甘心、更喜乐地履行本分——<em>如同对待父母一般</em>。"),
   (126, "第五诫的总范围是什么？", "履行我们在各种关系中<b>彼此相欠</b>的本分——作为在下者、在上者，或彼此同等者。")],
  core="问 124 把第五诫从「家庭伦理」扩展为<b>一切权柄关系的总诫</b>——家庭、教会、国家。而问 125 立刻给出制衡：既然在上者被称为「父母」，那么<em>权柄的性质就由「父母」这个称呼所规定</em>——权柄是为被管之人的益处而设的养育性权柄，不是为自己的利益而设的支配性权柄。",
  why="在一个等级社会里，这一诫极易被上位者单向利用。威敏的编排恰恰相反：问 127–128 讲在下者的本分与罪，问 129–130 讲在上者的本分与罪，问 131–132 讲同等者——<b>三种关系、六张清单，完全对称</b>。这个对称本身就是对权柄滥用的制度性批判。",
  cont="海德堡问 104 论第五诫极为简短：「我当向父母与一切在我之上的人显出一切的尊敬、爱与忠诚；以应有的顺服顺从他们一切良善的教导与惩治；<b>并且要忍耐他们的软弱与缺点，因为神乐意藉他们的手来治理我们。</b>」<em>最后一句是海德堡的独到之处</em>——它把顺服的根据从「在上者配得」转移到「神藉他们治理」，因而既要求顺服，又不美化在上者。威敏用六张清单达到同样的平衡，海德堡用一句话。",
  view="「良善的教导」（海德堡）与「合法的命令」（威敏问 127）都埋着同一个限定：<b>顺服不是无限的</b>。当在上者的命令与神的命令冲突时，「顺从神不顺从人是应当的」（徒5:29）。威敏信条 20:2 明文确立了这条例外，读大要理时务必一并记住。",
  app="问 124 的扩展意味着：这一诫对雇主与雇员、牧师与会众、教师与学生、官员与公民同样有效。读问 129–130 时，凡有任何权柄的人（包括作父母的）都应当对号入座。",
  keys="太22:39　太7:12　弗6:1–4　林前4:14–15　王下5:13　加4:19　帖前2:7–11"),

U("u28", "问127–133", "第五诫（下）：三组关系，六张清单",
  [(127, "在下者当向在上者尽的本分是什么？", "在心里、言语、举止上一切应有的敬重；为他们祷告感谢；效法他们的美德与恩典；甘心顺从他们<b>合法的</b>命令与劝告；恰当地顺服他们的责罚；按各人的身分与职位的性质，向他们的位格与权柄尽忠、护卫、维持；<em>包容他们的软弱，以爱心遮盖</em>，使他们和他们的治理得着尊荣。"),
   (128, "在下者对在上者所犯的罪是什么？", "疏忽上述本分；嫉妒、藐视、悖逆他们的位格与职位；咒骂、讥笑，以及一切顽梗与羞辱的行为，以致使他们与他们的治理蒙羞受辱。"),
   (129, "在上者当向在下者尽的本分是什么？", "照他们从神所领受的权柄与所处的关系，<b>爱他们、为他们祷告、祝福他们</b>；教导、劝告、警戒他们；嘉许、称赞、奖赏行善的；不悦、责备、管教行恶的；保护他们，并供给他们灵魂与身体所需的一切；并以庄重、智慧、圣洁、可作榜样的行事为人，使荣耀归神、尊荣归己，从而保守神所赐给他们的权柄。"),
   (130, "在上者所犯的罪是什么？", "除疏忽本分之外，<b>过度地寻求自己、自己的荣耀、安逸、利益或享乐</b>；命令不法之事，或命令在下者力所不能及之事；在恶事上出主意、鼓励、偏袒他们；在善事上劝阻、打击、冷待他们；不当地责罚他们；粗心地使他们暴露于伤害、试探与危险中，或撇下不顾；<em>惹他们的气</em>；或以不义、不慎、严酷或松懈的行为，羞辱自己、削弱自己的权柄。"),
   (131, "同等者当尽的本分是什么？", "彼此看重对方的尊严与价值，<b>彼此推让，恭敬人要彼此当先</b>；并为彼此的恩赐与长进而喜乐，如同自己的一样。"),
   (132, "同等者所犯的罪是什么？", "除疏忽本分之外，<b>轻看对方的价值、嫉妒对方的恩赐、为对方的长进或兴盛而忧闷</b>；并僭越地凌驾于彼此之上。"),
   (133, "第五诫所附的理由是什么？", "「使你的日子在耶和华你神所赐你的地上得以长久。」——这是明确的应许：凡遵守这诫的，必得长寿与亨通，<em>只要这合乎神的荣耀与他们自己的益处</em>。")],
  core="这七问的价值在于<b>它把抽象的「爱人如己」译成了可执行的关系伦理</b>。三组关系各有正反两张清单，共六张。问 130 尤其值得上位者反复读——它列出的第一项不是「暴虐」，而是「<em>过度地寻求自己的荣耀、安逸、利益或享乐</em>」。绝大多数权柄的败坏，都从这里开始。",
  why="1640 年代的英格兰正在重新定义一切权柄关系——国王与议会、主教与牧师、地主与佃农。威敏在这个时刻写下的不是「服从在上者」的单向训令，而是<b>双向的、对称的本分清单</b>。这在当时是有政治锋芒的：它意味着<em>权柄的合法性来自它是否履行本分</em>。",
  cont="欧陆信条在这一点上没有对应的细目——比利时信条第 36 条论政府，是从教会与政府的关系着眼，不涉及家庭与同侪。<b>这是大要理相对三项合一信条的一个真实增益</b>：一套完整的关系伦理学，至今仍是改革宗伦理教导中最实用的部分之一。",
  view="问 133 的应许被加了一个限定：「<em>只要这合乎神的荣耀与他们自己的益处</em>」。这是对成功神学式误读的预先防范——第五诫不是长寿保险单。约拿单孝敬扫罗，仍死在战场上。应许是真的，但它的兑现方式在神手里。",
  app="问 131–132 常被忽略，却最贴近日常：同事、同工、弟兄姊妹之间的关系。<b>「为彼此的恩赐与长进而喜乐，如同自己的一样」</b>——这一句是检验教会内嫉妒的照妖镜。当别人被称赞时我心里的第一反应，比我的信仰告白更诚实。",
  keys="玛1:6　彼前2:17　罗13:1–7　弗6:4　西3:19–21　罗12:10　腓2:3–4　彼前5:5　出20:12"),

U("u29", "问134–136", "第六诫：保全生命的积极本分",
  [(134, "第六诫是什么？", "「不可杀人。」"),
   (135, "第六诫所要求的本分是什么？", "一切谨慎的用心与合法的努力，去<b>保全自己与他人的生命</b>：抵挡一切意念与图谋、制伏一切激情、避开一切会导致不义夺取人命的场合、试探与作法；对暴力作正当的防卫；忍耐神的手，心思安静，心灵喜乐；<b>节制地使用饮食、医药、睡眠、劳动与娱乐</b>；以仁爱的意念、爱、怜悯、温柔、和善相待；言语举止和平、温和、有礼；宽容，乐意和好，忍耐并饶恕伤害，以善报恶；<em>安慰扶助困苦的人，保护并维护无辜的人</em>。"),
   (136, "第六诫所禁止的罪是什么？", "夺取自己或他人的生命（公义的刑罚、合法的战争、必要的自卫除外）；<b>疏忽或撤除维系生命所必需的合法手段</b>；有罪的怒气、恨恶、嫉妒、报复的欲望；一切过度的激情、扰乱人的忧虑；无节制地使用饮食、劳动与娱乐；挑衅的言语、欺压、争吵、殴打、伤害，以及一切会导致毁坏人生命的事。")],
  core="问 135 的清单几乎全是<b>积极的作为</b>——这是问 99 第四条规则（禁止即命令其反面）最漂亮的示范。「不可杀人」被读成「<em>你要用一切合法的努力保全生命</em>」：包括你自己的身体、你的情绪、你的睡眠、你的言语，以及那些困苦无告之人的处境。",
  why="把「有罪的怒气、恨恶、嫉妒」列入第六诫，直接承接主耶稣在太5:21–22 的解释。这不是清教徒的加码，是耶稣自己的解经。问 99 第二条规则（律法是属灵的，管到心思）在这里被完整兑现。",
  cont="海德堡问 105–107 论第六诫，问 106 问「这一诫只讲杀人吗？」答：「不；神藉着禁止杀人，教导我们祂<b>憎恶杀人的根源</b>——嫉妒、恨恶、忿怒与报复的心；在祂看来，这些都是隐藏的杀人。」问 107 再进一步：「那么不害邻舍就够了吗？」答：「不够；神既定罪嫉妒、恨恶与忿怒，就吩咐我们<em>爱邻舍如同自己，向他显出耐心、和平、温柔、怜悯与友善，尽力防止他受害，甚至以善待仇敌</em>。」<b>三问的推进结构（外在行为→内心根源→积极本分）与威敏两张清单的内容完全一致，只是海德堡用递进，威敏用并列。</b>",
  view="问 136 括号里的三项例外——<em>公义的刑罚、合法的战争、必要的自卫</em>——是历史上改革宗主流的立场，与再洗礼派的绝对和平主义相对。需要说明的是：这三项例外在今日各有其复杂的伦理讨论（死刑存废、正义战争论的适用），威敏只是确立了「并非一切夺取生命都违犯第六诫」这个原则，并未给出具体的应用判准。",
  app="问 135 里那句「<b>节制地使用饮食、医药、睡眠、劳动与娱乐</b>」，把作息与身体照料放进了第六诫。过劳、长期睡眠不足、忽视身体，在这套伦理里不是个人选择，是对第六诫的违犯。这一点在今日尤其值得听。",
  keys="出20:13　太5:21–26　弗4:26–27　罗12:17–21　箴24:11–12　徒16:28　创9:6"),

U("u30", "问137–139", "第七诫：贞洁，在身体与心思上",
  [(137, "第七诫是什么？", "「不可奸淫。」"),
   (138, "第七诫所要求的本分是什么？", "在<b>身体、心思、情感、言语与举止</b>上的贞洁；并在自己与他人身上保守这贞洁；看守眼目与一切的感官；节制；与贞洁的人来往；衣着端庄；<em>凡没有守独身恩赐的人当结婚</em>，夫妻相爱同居；在各自的呼召上殷勤劳作；躲避一切不洁的场合，抵挡一切相关的试探。"),
   (139, "第七诫所禁止的罪是什么？", "奸淫、淫乱、强暴、乱伦，以及一切违反本性的情欲；一切不洁的想像、意念、企图与情感；一切败坏污秽的言谈，或听这类言谈；放荡的眼神、无耻或轻浮的举止、不端庄的衣着；<b>禁止合法的婚姻，却纵容不合法的婚姻</b>；容许、纵容或经营娼寮；束缚人的独身誓愿，不当地延迟婚姻；同时有一个以上的配偶；不义的离婚或遗弃；懒惰、贪食、醉酒、与不贞洁的人来往；淫荡的歌曲、书籍、图画、舞蹈、戏剧；以及一切在自己或他人身上引致不洁的挑动或行为。"),
   ],
  core="问 138 最值得注意的是它把<b>婚姻本身列为第七诫「所要求的本分」</b>：「凡没有守独身恩赐的人当结婚」。第七诫不只是禁令，它同时肯定并保护婚姻这一制度。贞洁的正面形态不是压抑，而是<em>在正当处安放</em>。",
  why="问 139 中「<b>禁止合法的婚姻</b>」与「<b>束缚人的独身誓愿</b>」两项，是对罗马教强制神职独身制的直接指控——在改革宗看来，把神所许可的定为禁止，与把神所禁止的定为许可，是同一类罪。请注意它们与「容许娼寮」并列，这个并列本身就是论证。",
  cont="海德堡问 108–109 论第七诫。问 108 说：神「<b>咒诅一切不贞洁</b>；因此我们当从心里憎恶它，并在圣洁的婚姻中或在独身中，过贞洁而有节制的生活。」问 109 补上内在层面：「神既然定我们的身体与灵魂为圣灵的殿，就吩咐我们保守两者纯洁圣洁；因此祂<em>禁止一切不洁的行为、举止、言语、意念、欲望，以及一切引诱人行此事的</em>。」<b>「圣灵的殿」这个理由是海德堡特有的，也是最有力的——它把贞洁的根据从道德规范提升到了三一神的内住。</b>",
  view="问 139 的清单反映十七世纪英格兰的具体处境（当时的娼寮、戏剧、舞蹈争议）。读这类清单时必须回到问 99 的八条规则来读：清单不是穷举，而是<b>同一条原则在当时处境中的具体例举</b>。今日的对应处境不同，原则却未变——<em>凡在自己或他人身上引致不洁的挑动</em>，这一句是这张清单真正的判准。",
  app="问 138 的「看守眼目与一切的感官」在今天有了前所未有的重量。这一诫的战场在十七世纪主要是在人际场合，今日则主要在屏幕上。同样一条原则，同样一个本分：<b>管理入口</b>。",
  keys="出20:14　太5:27–28　林前7:2,9,36　林前6:18–20　帖前4:3–5　箴5:8　弗5:3–4"),

U("u31", "问140–142", "第八诫：财产、工作与公平",
  [(140, "第八诫是什么？", "「不可偷盗。」"),
   (141, "第八诫所要求的本分是什么？", "在人与人的契约与交易中存<b>诚实、信实与公义</b>；各归其应得；把不法扣留的物归还原主；照自己的能力与别人的需要，甘心施与并借贷；在对世上财物的判断、意愿与情感上有节制；<b>有远见地谋取、保守、使用并处置那些维持生活所需、与自己身分相称的东西</b>；有一份合法的职业并在其中殷勤；节俭；避免不必要的诉讼与作保或类似的牵累；<em>并以一切公正合法的手段，谋求、保守并增进他人的产业与外在的家业，如同自己的一样</em>。"),
   (142, "第八诫所禁止的罪是什么？", "除疏忽上述本分之外：偷窃、抢劫、<b>拐卖人口</b>、收受赃物；欺诈交易、使用不公平的法码与量器、挪移地界、在契约或受托事务上不义不忠；欺压、勒索、放高利贷、贿赂、缠讼、不义的圈地与<em>毁村</em>（1788 年美国版改为「掠夺」）；囤积货物抬高物价；不法的职业；以及一切以不义手段谋取他人财物的方式；贪婪；过度看重与贪恋世上财物；在谋取、保守、使用它们上有不信与扰乱人的忧虑；嫉妒他人的兴盛；同样还有<b>懒惰、挥霍、赌博式的浪费</b>，以及一切不当损害自己家业、使自己无法正当享用神所赐之物的行为。")],
  core="问 141 最后一句是这一诫的高峰：<b>「以一切公正合法的手段，谋求、保守并增进<em>他人</em>的产业，如同自己的一样。」</b>「不可偷盗」被读到了它的正面极限——不止不夺取别人的，还要积极促进别人的富足。这在任何伦理体系中都是罕见的要求。",
  why="「拐卖人口」（man-stealing）明确列在问 142 之首列，源自出21:16 与提前1:10。这一条在十八至十九世纪成为美国长老会内部废奴论证的重要依据之一——大要理白纸黑字地把拐卖人口列为违犯第八诫的重罪。<br>同一问中的「毁村」（depopulations，指圈地运动中驱散整村佃农）在 1788 年被美国版改成「掠夺」（depredation）。这处改动的动机在史家中有争议，其中一种解释认为原词会直接指控当时对原住民的处置。<b>无论动机为何，这一改动记录了一份信条与它所在社会之间的真实张力。</b>",
  cont="海德堡问 110–111 论第八诫。问 110 与威敏几乎重合，同样列出高利贷、不公平法码、贪婪、浪费。<b>问 111 是海德堡的收束句，也是这一诫最好的总结：「神在这一诫中吩咐我什么？<em>我当尽我所能、也当尽我所应当，去促进邻舍的益处；待人如同我愿意人待我；并忠心作工，好使我能周济穷乏的人。</em>」</b>——工作的目的被明确地连到了济贫上。",
  view="问 141 把「<b>避免不必要的诉讼与作保</b>」列为本分，这是十七世纪商业伦理的具体应用，其背后的原则是：<em>不要把自己置于会连累他人、或使自己无法履行本分的财务牵累中</em>。这条原则在信用消费时代反而更加锋利。",
  app="问 142 末段把「<b>使自己无法正当享用神所赐之物</b>」也列为罪，这一点常被清教徒的刻板印象掩盖。<em>过度的吝啬与过度的挥霍，在这张清单上并列</em>。财物既不是偶像，也不是敌人，而是受托的产业。",
  keys="出20:15　弗4:28　利25:35　诗15:2–5　箴27:23–27　提前5:8　出21:16　提前1:10　路3:14"),

U("u32", "问143–145", "第九诫：真相与名声——全篇最长的一张清单",
  [(143, "第九诫是什么？", "「不可作假见证陷害人。」"),
   (144, "第九诫所要求的本分是什么？", "在人与人之间<b>保守并促进真相</b>，也保守邻舍与自己的<b>好名声</b>；出面为真理站立；在审判与公义之事上、并在一切别的事上，从心里诚实、自由、清楚、完整地说真话，且只说真话；以仁爱看待邻舍；爱慕、渴望并因他们的好名声而喜乐；为他们的软弱忧伤并遮盖；乐意承认他们的恩赐与恩典；为他们的清白辩护；<b>乐于接受好的报告，不愿听信坏的报告</b>；阻止搬弄是非者、谄媚者与毁谤者；爱护自己的好名声，必要时加以辩护；守合法的诺言；<em>凡是真实的、可敬的、可爱的、有美名的，都要思念并实行</em>。"),
   (145, "第九诫所禁止的罪是什么？", "一切损害真相与邻舍（以及自己）好名声的事，尤其是在公开审判中：作伪证、唆使伪证、明知是恶事仍出面辩护、以气势压倒真理；作出不义的判决；称恶为善、称善为恶；伪造；隐瞒真相；在当伸张公义时不当地缄默，在罪恶需要责备或申诉时闭口不言；<b>不合时宜地说真话，或出于恶意说真话，或把真话曲解成错误的意思</b>；说谎、毁谤、背后中伤、贬损、搬弄是非、私下嚼舌、讥讽、辱骂、轻率苛刻与偏颇的论断；曲解人的意图、言语与行为；谄媚；虚荣自夸；把自己或别人看得或说得<em>过高或过低</em>；否认神所赐的恩赐与恩典；夸大小过失；在当坦白认罪时隐藏、辩解或轻描淡写；不必要地揭露他人的软弱；散布谣言、接受并支持恶意的报告、堵住耳朵不听正当的辩护；恶意的猜疑；嫉妒或为他人应得的声誉忧闷；企图或渴望损害它，并以他人的羞辱为乐；轻蔑的藐视、盲目的崇拜；违背合法的诺言；忽略美名之事，或自己行、或不阻止他人行那些招致恶名的事。")],
  core="这是全篇<b>最长的一问</b>，也是最能显出大要理特色的一问。它的核心不是「不可说谎」这么窄，而是<b>真相（truth）与名声（good name）的双重保护</b>。名声在这套伦理里被当作准财产：损毁他人名声，与偷窃他人财物同罪。",
  why="问 145 开头点明「<b>尤其是在公开审判中</b>」——第九诫的原始处境是法庭作证。清教徒把它扩展到日常言语，但保留了法庭为范式：<em>你在背后谈论某人时，实际上是在缺席审判中作证，而被告不在场，无人替他辩护</em>。这个类比一旦成立，整张清单就都顺理成章了。",
  cont="海德堡问 112 论第九诫，简短却锋利：「我不可作假见证陷害人，不可歪曲人的话，不可作搬弄是非与毁谤的人，不可不听申辩就定人的罪；<b>凡说谎与欺骗，都是魔鬼自己的作为，必招致神极重的忿怒</b>；我当在审判与一切事务上爱护真理，诚实地说出并承认它；<em>并且尽我所能，维护并促进邻舍的荣誉与好名声</em>。」<br>「说谎是魔鬼自己的作为」（约8:44）这个根据，是海德堡给出的、威敏没有明说的神学重锤。",
  view="问 145 里三项最容易被忽略、却最需要听的：<br><b>一、「不合时宜地说真话，或出于恶意说真话」</b>——真话说得不是时候、或为了伤人而说，同样违犯第九诫。这一条彻底封死了「我只是说实话」这个万能借口。<br><b>二、「把自己看得过高<em>或过低</em>」</b>——自贬也是违犯第九诫，因为它同样不是真相。<br><b>三、「恶意的猜疑」</b>——在心里定人的罪，不需要说出口就已经违犯了。",
  app="有一条可以每天使用的检核：今天我谈论的每一个不在场的人，如果他就站在旁边听，我会用同样的措辞、同样的语气、说同样的内容吗？这一问几乎涵盖了问 145 的大半。",
  keys="出20:16　亚8:16　箴31:8–9　弗4:25　彼前3:16　箴17:9　雅4:11　太7:1　腓4:8"),

U("u33", "问146–148", "第十诫：心的知足",
  [(146, "第十诫是什么？", "「不可贪恋人的房屋，也不可贪恋人的妻子、仆婢、牛驴，并他一切所有的。」"),
   (147, "第十诫所要求的本分是什么？", "对自己的景况有<b>充分的知足</b>；并且对邻舍存这样一种仁爱的心，以致我们内心一切关乎他的意念与情感，都<em>倾向并促进他的一切益处</em>。"),
   (148, "第十诫所禁止的罪是什么？", "对自己景况的<b>不知足</b>；嫉妒邻舍的好处并为之忧闷；以及一切对属于他的任何东西<em>不当的心思与情感</em>。")],
  core="第十诫是唯一一条<b>完全无法从外在行为判断</b>的诫命。它把整部律法收回到心里——这正是保罗在罗7:7 所说的：「若不是律法说『不可起贪心』，我就不知何为贪心。」<em>第十诫是律法用来杀死自义的那一诫。</em>",
  why="问 147 的措辞极精：所要求的不是「不贪」（消极），而是「<b>知足</b>」加上「<b>内心一切意念都促进邻舍的益处</b>」（积极）。这再一次示范了问 99 的第四条规则。同时它揭示了贪心的本质——<em>贪心不只是想要更多，而是内心对邻舍的处境采取了敌对的姿态</em>。",
  cont="海德堡问 113 论第十诫：「就是<b>连最微小的、违背神任何诫命的意念或思想，都不可在我们心里兴起</b>；我们当终身以全心全意恨恶一切的罪，喜爱一切的义。」——随后问 114 与 115 立刻接上前文已引的那两问：「那么归正的人能完全遵守这些诫命吗？」答：「不能；连最圣洁的人在今生也不过是这顺服的一个<em>微小的开端</em>。」<b>海德堡在这里的次序（第十诫 → 无人能守 → 为何仍要传讲）与威敏问 148 → 149 → 150 完全一致。两份文件在此处的收尾动作几乎一模一样。</b>",
  view="问 148 中「<em>为邻舍的好处忧闷</em>」（grieving at the good of our neighbour）是一个惊人的精确诊断：贪心的最深形态不是「我想要他的东西」，而是「<b>他有这东西这件事本身让我不舒服</b>」。前者还可以用获取来平息，后者只能用他人的失去来平息。这是嫉妒与贪心的交界处。",
  app="第十诫提供了一种独特的祷告：不是求神除去我想要的东西，而是求神改变我对邻舍的姿态——从「他有而我没有」的比较，转为「愿他一切都好」的祝愿。这个转变一旦发生，贪心就失去了土壤。",
  keys="出20:17　罗7:7–8　来13:5　提前6:6　伯31:29　罗12:15　加5:26　雅3:14–16"),

U("u34", "问149–152", "收束：无人能守全，罪有轻重，一切罪当受什么",
  [(149, "有人能完全遵守神的诫命吗？", "<b>无人能够</b>——无论是靠自己，还是靠今生所领受的任何恩典——完全地遵守神的诫命；乃是天天在思想、言语与行为上违犯它们。"),
   (150, "一切违犯神律法的罪，都同样可憎吗？", "并非同样可憎。有些罪就其本身、并因着若干加重的因素，在神眼中<b>比别的罪更可憎</b>。"),
   (151, "使某些罪更可憎的加重因素是什么？", "四类：<b>一、从犯罪的人</b>——他的年龄、经验、恩赐、职位、榜样的影响力；<b>二、从被冒犯的对象</b>——是否直接冒犯神、冒犯祂的属性与敬拜？是否冒犯了在上者、或与我们有特别关系的人？是否伤及众人？<b>三、从罪行本身</b>——干犯了哪一诫、是否明知故犯、是否公开、是否累犯、是否引人同犯、有无悔改？<b>四、从时间与地点</b>——是否在主日、在公共敬拜中、在蒙警戒或立志之后、在别人可能因此绊倒之时？"),
   (152, "每一样罪在神手中应得什么？", "每一样罪——<b>即使是最小的</b>——既是干犯神的主权、良善与圣洁，并干犯祂公义的律法，就应当受祂在今生与来世的忿怒与咒诅；<em>除了藉着基督的血之外，无法得着赎罪</em>。")],
  core="这四问是整个律法部分的<b>出口</b>，也是通往问 153（蒙恩之道）的桥。次序极重要：先说无人能守全（问149），再说罪有轻重（问150–151），最后说最小的罪也当受咒诅、唯有基督的血能赎（问152）。<b>问 152 的最后半句，是整部律法部分唯一的出路。</b>",
  why="问 150 「罪有轻重」针对的是斯多亚派与某些激进派「一切罪等同」的主张。但它同时被小心地限定在问 152 之内——<em>罪有轻重，不代表有哪一样罪轻到可以不必赎</em>。这两问必须一起读，拆开任何一问都会出事。",
  cont="海德堡在这里的对应是问 114–115（已在前文引述）：「连最圣洁的人在今生也不过是这顺服的一个微小的开端」，以及「神为何还要如此严格地传讲十诫？」<b>然后海德堡立刻转入第三部分的祷告段落（问116起）</b>——与威敏从问 153 转入蒙恩之道，结构上是同一个动作：<em>律法把人逼到尽头，尽头处摆着蒙恩的管道</em>。",
  view="问 151 的四把尺常被误用为「所以我的罪不算重」。原文的用意恰好相反：<b>它是省察的工具，不是自我宽免的滑梯</b>。请注意第一类的内容——身分越高、恩赐越多、职位越重、影响越大，罪就越重。这张尺量得最狠的，恰恰是牧者、长老、教师与父母。",
  app="问 152 的「即使是最小的罪」与问 150 的「罪有轻重」需要同时握在手里：<em>面对自己的罪时用问 152</em>（不可轻看任何一样），<em>面对别人的罪时用问 151</em>（要有分辨，不可一概而论）。次序反过来，就成了苛待别人、宽待自己。",
  keys="传7:20　约一1:8,10　加5:17　结8:6,13,15　约19:11　路12:47–48　罗6:23　加3:10　来9:22　约一1:7"),
]


